import{_ as t,o as a,c as s,ag as n}from"./chunks/framework.BSsJcWLc.js";const u=JSON.parse('{"title":"Web Layer","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/web-layer.md","filePath":"architecture/web-layer.md"}'),o={name:"architecture/web-layer.md"};function r(i,e,d,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="web-layer" tabindex="-1">Web Layer <a class="header-anchor" href="#web-layer" aria-label="Permalink to &quot;Web Layer&quot;">​</a></h1><p>The web layer connects the Vue 3 frontend to the processing pipeline via FastAPI.</p><h2 id="backend-services" tabindex="-1">Backend Services <a class="header-anchor" href="#backend-services" aria-label="Permalink to &quot;Backend Services&quot;">​</a></h2><p>Services are singletons created at startup and manage distinct concerns:</p><table tabindex="0"><thead><tr><th>Service</th><th>Responsibility</th></tr></thead><tbody><tr><td><strong>ConfigService</strong></td><td>Holds configuration state, builds <code>PipelineConfig</code></td></tr><tr><td><strong>PipelineService</strong></td><td>Pipeline lifecycle (start/stop), mode control, viz config</td></tr><tr><td><strong>StreamService</strong></td><td>LSL stream discovery and configuration</td></tr><tr><td><strong>ModeService</strong></td><td>Mode instance CRUD</td></tr><tr><td><strong>PreflightService</strong></td><td>Pre-start validation checks</td></tr><tr><td><strong>MLService</strong></td><td>Data loading, online training (subprocess), decoder management, evaluation reaggregation</td></tr><tr><td><strong>DataService</strong></td><td>Database access (studies, recordings, decoders, datasets)</td></tr><tr><td><strong>StreamManagerService</strong></td><td>File/MOABB replay stream management</td></tr></tbody></table><p>Services communicate through direct references. <code>ConfigService</code> aggregates state from <code>StreamService</code> and <code>ModeService</code> to build the pipeline configuration.</p><h2 id="websocket-channels" tabindex="-1">WebSocket Channels <a class="header-anchor" href="#websocket-channels" aria-label="Permalink to &quot;WebSocket Channels&quot;">​</a></h2><p>Real-time data flows from the pipeline to browser clients via <code>QueueBridge</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SharedRingBuffer ──► run_visualization_bridge() ──► QueueBridge ──► WebSocket ──► Browser</span></span>
<span class="line"><span>visualization_queue ───────────────────────────┘</span></span>
<span class="line"><span>SharedState ──────────► run_telemetry_poller() ──► QueueBridge ──► WebSocket ──► Browser</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Channel</th><th>Format</th><th>Rate</th><th>Content</th></tr></thead><tbody><tr><td><code>/ws/visualization</code></td><td>msgpack</td><td>~100Hz</td><td>Raw signal data (decimated 5×, preprocessed)</td></tr><tr><td><code>/ws/telemetry</code></td><td>JSON</td><td>1Hz</td><td>CPU, memory, stream latency, mode metrics, channel quality</td></tr><tr><td><code>/ws/mode_data</code></td><td>msgpack</td><td>event-driven</td><td>Mode output data (predictions, ERP, band power)</td></tr><tr><td><code>/ws/training</code></td><td>JSON</td><td>per-epoch</td><td>Training progress, completion, errors</td></tr></tbody></table><p><strong>QueueBridge</strong> (<code>ws/bridge.py</code>) drains multiprocessing queues from a thread pool and fans out to WebSocket subscribers. Slow clients get frames dropped (no backpressure). <code>enable_history()</code> lets new subscribers receive recent frames on connect.</p><p><strong><code>run_visualization_bridge()</code></strong> (<code>ws/visualization_bridge.py</code>) — async task spawned/cancelled on recording start/stop. Reads raw signal data from the primary stream&#39;s ring buffer, applies preprocessing (CAR + bandpass), monitors channel quality, broadcasts via QueueBridge. Mode outputs drained from <code>visualization_queue</code> to <code>mode_data</code> channel.</p><p><strong>Online Training Task</strong> (<code>app.py</code>) -- Background task that waits for recording start, then drains <code>training_queue</code> (from SynchronousMode or manual requests). MLService loads data from SWMR HDF5, trains in a subprocess, publishes decoder path to SharedState for hot-swap.</p><p><strong>Background Optimizer</strong> (<code>ml/search/optuna_runner.py</code>, managed by <code>ml_service.py</code>) -- Per-mode asyncio tasks running Optuna search during recording. Loads fresh session data, searches within mode&#39;s model type, promotes winners (5%+ improvement) via SharedState. Profiles (quick/balanced/full) control trial count and scope.</p><h2 id="frontend-architecture" tabindex="-1">Frontend Architecture <a class="header-anchor" href="#frontend-architecture" aria-label="Permalink to &quot;Frontend Architecture&quot;">​</a></h2><ul><li><strong>Pinia stores</strong>: config, pipeline, streams, modes, data, ml, streamManager, telemetry, visualization</li><li><strong>Composables</strong>: <code>useWebSocket</code>, <code>useRingBuffer</code>, <code>useToast</code>, <code>useDecoderPicker</code>, <code>useSessionEvents</code></li><li><strong>uPlot</strong>: real-time signal visualization at 30fps</li><li><strong>PrimeIcons</strong>, <strong>Tailwind CSS</strong></li></ul><h3 id="views-components" tabindex="-1">Views &amp; Components <a class="header-anchor" href="#views-components" aria-label="Permalink to &quot;Views &amp; Components&quot;">​</a></h3><p>Three routed views: <strong>ControlView</strong> (<code>/</code>), <strong>DataExplorerView</strong> (<code>/data</code>), <strong>MLWorkbenchView</strong> (<code>/ml</code>). ControlView embeds <code>DashboardView</code> as the live monitoring panel. Components are organized in feature-based subdirectories: <code>common/</code>, <code>config/</code>, <code>dashboard/</code>, <code>data/</code>, <code>display/</code>, <code>layout/</code>, <code>ml/</code>, <code>stream-manager/</code>.</p><h3 id="data-flow" tabindex="-1">Data Flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data Flow&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REST API → Pinia store → Vue component (reactive)</span></span>
<span class="line"><span>WebSocket → composable → ring buffer → uPlot (real-time)</span></span></code></pre></div><p>Config flow: UI form -&gt; store action -&gt; <code>PUT /api/config/*</code> -&gt; service state. Pipeline reads at start via <code>ConfigService.build_configuration()</code>.</p><h2 id="pipeline-integration" tabindex="-1">Pipeline Integration <a class="header-anchor" href="#pipeline-integration" aria-label="Permalink to &quot;Pipeline Integration&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Frontend            Backend              Pipeline Subprocess</span></span>
<span class="line"><span>  │                    │                        │</span></span>
<span class="line"><span>  ├─POST /start──────►│                        │</span></span>
<span class="line"><span>  │                    ├──_run_session_io()─────►│ (DB, files)</span></span>
<span class="line"><span>  │                    ├──orchestrator.start()──►│ (DAQ, saver, session, metrics)</span></span>
<span class="line"><span>  │                    ├──start_modes()─────────►│ (sync, async, nfb)</span></span>
<span class="line"><span>  │                    │                        │</span></span>
<span class="line"><span>  │◄──/ws/telemetry───┤◄──SharedState──────────┤ (1Hz polling)</span></span>
<span class="line"><span>  │◄──/ws/visualization┤◄──ring buffer─────────┤ (VizBridge reads + preprocesses)</span></span>
<span class="line"><span>  │◄──/ws/mode_data───┤◄──viz_queue────────────┤ (mode outputs)</span></span>
<span class="line"><span>  │                    │                        │</span></span>
<span class="line"><span>  ├─POST /stop───────►│                        │</span></span>
<span class="line"><span>  │                    ├──orchestrator.stop()───►│ (graceful shutdown)</span></span></code></pre></div>`,23)])])}const h=t(o,[["render",r]]);export{u as __pageData,h as default};
